<script setup>
import { ref,computed,watch,onMounted } from 'vue';
import { useRoute } from 'vue-router';
import { api } from '../../services/api.js';
import { useStorefront } from '../../services/storefront.js';
import { storefrontSlug } from '../../services/storeHost.js';
import { StoreCopy } from '../../services/storeCopy.js';
import { StoreTextLayout } from '../../services/storeNavigation.js';
import { sectionSpacing } from '../../services/design.js';
import { money } from '../../services/format.js';
import { notify } from '../../services/notifications.js';
import ProductImage from '../../components/ProductImage.vue';
import ProductCard from '../../components/ProductCard.vue';
import Icon from '../../components/Icon.vue';
const sf=useStorefront(),route=useRoute(),recommendations=ref([]),loading=ref(false),error=ref('');
const currentSlug=computed(()=>storefrontSlug(route));
const copy=new StoreCopy(()=>sf.design.value);
const cart=computed(()=>sf.cart.value),design=computed(()=>sf.design.value.cart);
const invalid=computed(()=>cart.value.state.items.some(i=>i.unavailable||i.type!=='digital'&&!i.madeToOrder&&i.quantity>i.stock));
function setQuantity(item,event){try{cart.value.setQuantity(item.key,Number(event.target.value));}catch(e){event.target.value=item.quantity;notify.error(e.message);}}
async function refresh(){loading.value=true;error.value='';try{await cart.value.refresh(sf.getProduct);}catch(e){error.value=e.message;}finally{loading.value=false;}}
async function recommend(){const ids=cart.value.state.items.map(i=>i.productId);if(!ids.length){recommendations.value=[];return;}try{recommendations.value=sf.isPreview.value?sf.products.value.filter(p=>!ids.includes(p._id)).slice(0,3):await api.post(`/public/stores/${currentSlug.value}/recommendations`,{productIds:ids});}catch{recommendations.value=[];}}
watch(()=>cart.value.state.items.map(i=>i.productId).join(','),recommend,{immediate:true});onMounted(refresh);
</script>
<template><div class="store-cart-page store-section" :class="'cart-layout-' + design.layout" :style="{...sectionSpacing(design),...StoreTextLayout.style(design.textAlign)}" :dir="StoreTextLayout.direction(design.textDirection)"><div class="store-page-heading"><span class="store-eyebrow">{{copy.text('cartEyebrow')}}</span><h1>{{design.title}}</h1><p class="store-muted">{{copy.text('cartSubtitle')}}</p></div><div v-if="!cart.state.items.length" class="store-empty"><Icon name="cart" :size="48"/><h2>{{copy.text('cartEmptyTitle')}}</h2><p>{{design.emptyText}}</p><RouterLink :to="sf.link()" class="store-button">{{copy.text('cartEmptyButton')}} <Icon name="arrow-right" :size="17"/></RouterLink></div><template v-else><div v-if="error" class="notice error">{{error}} <button class="link" @click="refresh">Actualizar carrito</button></div><div v-if="invalid" class="notice warning">Uno o más productos ya no están disponibles en la cantidad elegida. Actualizá el carrito para continuar.</div><div class="cart-layout"><div class="cart-items"><article v-for="item in cart.state.items" :key="item.key" class="cart-line" :class="{'no-images':!design.showImages}"><RouterLink v-if="design.showImages" :to="sf.link('/producto/'+item.productId)" class="cart-line-image"><ProductImage :src="item.image" :name="item.name" :type="item.type"/></RouterLink><div class="cart-line-info"><RouterLink :to="sf.link('/producto/'+item.productId)"><h3>{{item.name}}</h3></RouterLink><span v-if="item.variantName" class="store-muted">{{item.variantName}}</span><span class="cart-unit-price">{{copy.text('cartUnitPrice',{amount:money(item.price)})}}</span><span v-if="item.unavailable" class="error-text">Producto no disponible</span><span v-else-if="item.type!=='digital'&&!item.madeToOrder&&item.quantity>item.stock" class="error-text">Quedan {{item.stock}} unidades</span></div><div class="cart-line-controls"><label class="cart-quantity-label"><span>{{copy.text('quantity')}}</span><input :value="item.quantity" @change="setQuantity(item,$event)" type="number" min="1" max="99" :aria-label="(copy.text('quantity')||'Cantidad')+' · '+item.name" :title="copy.text('quantity')||'Cantidad'"/></label><strong>{{money(item.quantity*item.price)}}</strong><button :aria-label="(copy.text('remove')||'Quitar')+' · '+item.name" :title="copy.text('remove')||'Quitar producto'" @click="cart.remove(item.key)"><Icon name="trash" :size="18"/></button></div></article><div v-if="design.showNotes" class="field cart-notes"><label for="cart-notes">{{copy.text('cartNotesLabel')}}</label><textarea id="cart-notes" :value="cart.state.notes" @input="cart.notes($event.target.value)" maxlength="1500" :placeholder="copy.text('cartNotesPlaceholder')"></textarea></div><RouterLink v-if="design.showContinueShopping" :to="sf.link()" class="store-continue"><Icon name="arrow-left" :size="17"/> {{copy.text('continueShopping')}}</RouterLink></div><aside class="cart-summary" :class="'cart-summary-' + design.summaryStyle"><span class="store-eyebrow">{{copy.text('cartSummaryEyebrow')}}</span><h2 class="cart-summary-heading">{{copy.text('cartSummaryTitle')}}</h2><div><span>{{copy.text('cartItems',{count:cart.count})}}</span><strong>{{money(cart.subtotal)}}</strong></div><div class="store-muted"><span>{{copy.text('delivery')}}</span><span>{{copy.text('cartDeliveryPending')}}</span></div><div class="cart-total"><strong>{{copy.text('subtotal')}}</strong><strong>{{money(cart.subtotal)}}</strong></div><p class="store-muted">{{copy.text('cartDeliveryHint')}}</p><RouterLink v-if="!invalid&&!loading&&!error" :to="sf.link('/checkout')" class="store-button">{{design.buttonText}} <Icon name="arrow-right" :size="17"/></RouterLink><button v-else class="store-button" disabled>{{loading?'Actualizando…':'Revisá tu carrito'}}</button><span class="cart-trust"><Icon name="shield" :size="16"/>{{design.trustMessage}}</span></aside></div><section v-if="design.showRecommendations && recommendations.length" class="store-related"><span class="store-eyebrow">{{copy.text('cartRecommendationsEyebrow')}}</span><h2>{{design.recommendationTitle}}</h2><div class="store-product-grid"><ProductCard v-for="item in recommendations" :key="item._id" :product="item"/></div></section></template></div></template>

<style scoped>
.cart-summary{top:calc(var(--store-header-offset,82px) + 24px)}.cart-summary-heading{font-size:1.3rem;line-height:1.25;letter-spacing:-.03em;margin:0 0 24px;font-weight:600;overflow-wrap:anywhere}.cart-summary>div{gap:15px}.cart-line-info{min-width:0}.store-page-heading :is(h1,p){overflow-wrap:anywhere}.cart-line-controls{direction:ltr}.cart-quantity-label{display:flex;flex-direction:column;gap:5px;font-size:.58rem;color:var(--store-muted);max-width:100%;text-align:center}.cart-quantity-label span{max-width:70px;overflow-wrap:anywhere}.cart-quantity-label input{width:60px;max-width:100%;padding:9px;border:1px solid var(--store-line);border-radius:6px;background:var(--store-surface);color:var(--store-text);font:inherit;font-size:.76rem;text-align:center}.cart-line-info>span{overflow-wrap:anywhere}
</style>
